import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsv(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n')
  ) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: export requires admin role');
  }

  const tasks = Array.from(
    (taskManager as unknown as { tasks: Map<string, { id: string; title: string; status: string; assignee: string; createdAt: number }> }).tasks.values()
  );

  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) =>
    [
      escapeCsv(t.id),
      escapeCsv(t.title),
      escapeCsv(t.status),
      escapeCsv(t.assignee),
      String(t.createdAt),
    ].join(',')
  );

  record({
    action: 'export',
    userId,
    details: `exported ${tasks.length} tasks`,
    timestamp: Date.now(),
  });

  return [header, ...rows].join('\n');
}
