import { findById, validateExists } from './users.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

type AllowedTransitions = {
  [K in Task['status']]?: Task['status'][];
};

const ALLOWED_TRANSITIONS: AllowedTransitions = {
  open: ['in_progress'],
  in_progress: ['done'],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (input.title.trim() === '') {
      throw new Error('Title must not be empty');
    }

    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: task.createdAt,
    });

    return task;
  }

  getTask(id: string): Task | null {
    const cached = this.cache.get<Task>(id);
    if (cached !== null) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, newStatus: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = ALLOWED_TRANSITIONS[task.status];
    if (!allowed || !allowed.includes(newStatus)) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${newStatus}`
      );
    }

    task.status = newStatus;

    // Invalidate cache entry for this task
    this.cache.invalidate(id);

    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: `status changed to ${newStatus}`,
      timestamp: Date.now(),
    });

    return task;
  }

